<style>
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap');
*{box-sizing:border-box;margin:0;padding:0;}*:hover{background:inherit !important;color:inherit !important;transform:none !important;box-shadow:inherit !important;border:inherit !important;opacity:inherit !important;filter:none !important;}
html,body{margin:0;padding:0;overflow-x:hidden;width:100%;height:100%;box-sizing:border-box;}
.testimonial-carousel{width:100%;max-width:1440px;margin:0 auto;padding:0;font-family:'Poppins',sans-serif;position:relative;display:flex;align-items:center;justify-content:center;z-index:1;}
.carousel-container{position:relative;overflow:hidden;border-radius:20px;width:100%;height:85vh;min-height:500px;cursor:grab;user-select:none;margin:0;z-index:1;}
.carousel-container:active{cursor:grabbing;}
.testimonial-track{display:flex;transition:transform 0.5s cubic-bezier(0.25,0.46,0.45,0.94);will-change:transform;height:100%;align-items:center;transform:translateX(0);width:100%;margin:0 auto;}
.testimonial-item{flex:0 0 calc(100% - 30px);height:100%;border-radius:20px;background-size:cover;background-position:center;background-repeat:no-repeat;position:relative;cursor:pointer;transition:all 0.5s cubic-bezier(0.25,0.46,0.45,0.94);margin-right:30px;box-sizing:border-box;}
@media (min-width:993px){.testimonial-item{background-size:cover;background-position:center 20%;}}
.testimonial-item.active{z-index:2;}
.testimonial-overlay{position:absolute;inset:0;background:transparent;display:flex;align-items:center;justify-content:flex-start;padding:80px 60px;border-radius:20px;opacity:0;transition:opacity 0.3s ease;}
.testimonial-item.active .testimonial-overlay{opacity:1;}
.testimonial-content{text-align:left;max-width:50%;width:50%;transform:translateY(20px);transition:transform 0.3s ease;}
.testimonial-item.active .testimonial-content{transform:translateY(0);}
.testimonial-text{font-size:18px;line-height:1.5;color:#fff;margin-bottom:40px;font-style:italic;text-shadow:2px 2px 4px rgba(0,0,0,0.8);font-weight:400;}
.author-info{margin-top:30px;}
.author-info h4{margin:0 0 12px 0;color:#fff;font-size:24px;font-weight:700;letter-spacing:1px;text-transform:uppercase;text-shadow:2px 2px 4px rgba(0,0,0,0.8);}
.author-info span{color:#fff;font-size:20px;font-weight:600;text-shadow:2px 2px 4px rgba(0,0,0,0.8);}
.carousel-nav{position:absolute;top:50%;transform:translateY(-50%);width:100%;display:flex;justify-content:space-between;padding:0 40px 0 15px;left:0;pointer-events:none;z-index:1000;}
.nav-btn{background:rgba(255,255,255,0.4);border:none;width:25px;height:25px;border-radius:50%;cursor:pointer;box-shadow:0 1px 6px rgba(0,0,0,0.1);transition:all 0.3s ease;pointer-events:auto;color:#333;display:flex;align-items:center;justify-content:center;z-index:1001;position:relative;touch-action:manipulation;-webkit-tap-highlight-color:transparent;-webkit-touch-callout:none;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none;}

.nav-btn svg{width:10px;height:10px;}

.carousel-dots{position:absolute;bottom:30px;left:50%;transform:translateX(-50%);display:flex;justify-content:center;gap:15px;z-index:1000;background:rgba(0,0,0,0.3);padding:10px 20px;border-radius:25px;backdrop-filter:blur(10px);}
.dot{width:12px;height:12px;border-radius:50%;background:rgba(255,255,255,0.4);cursor:pointer;transition:all 0.3s ease;border:2px solid rgba(255,255,255,0.6);z-index:1001;position:relative;touch-action:manipulation;-webkit-tap-highlight-color:transparent;-webkit-touch-callout:none;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none;}
.dot.active{background:#fff;transform:scale(1.5);box-shadow:0 2px 8px rgba(0,0,0,0.4);border:2px solid #fff;}

@media (max-width:1400px){.testimonial-text{font-size:16px;}.author-info h4{font-size:22px;}.author-info span{font-size:18px;}.testimonial-content{max-width:55%;width:55%;}.testimonial-item{background-position:center 15%;}}
@media (max-width:1366px) and (max-height:768px){.carousel-container{height:95vh;}.testimonial-item{background-position:center 10%;}.testimonial-overlay{padding:30px 25px;}.testimonial-text{font-size:13px;}.author-info h4{font-size:17px;}.author-info span{font-size:14px;}.testimonial-content{max-width:42%;width:42%;}}
@media (max-width:1366px) and (min-height:769px){.carousel-container{height:85vh;}.testimonial-item{background-position:center 12%;}.testimonial-overlay{padding:40px 35px;}.testimonial-text{font-size:15px;}.author-info h4{font-size:19px;}.author-info span{font-size:16px;}.testimonial-content{max-width:48%;width:48%;}}
@media (max-width:1200px){.testimonial-text{font-size:15px;}.author-info h4{font-size:20px;}.author-info span{font-size:16px;}.carousel-container{height:75vh;}.testimonial-content{max-width:60%;width:60%;}.testimonial-item{background-position:center 20%;}}
@media (max-width:992px){.testimonial-text{font-size:14px;}.author-info h4{font-size:18px;}.author-info span{font-size:14px;}.carousel-container{height:65vh;}.testimonial-content{max-width:65%;width:65%;}.testimonial-item{background-position:center 25%;}}
@media (max-width:768px){.testimonial-carousel{padding:0;margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;position:relative;width:100%;overflow-x:hidden;box-sizing:border-box;}.carousel-container{height:65vh;border-radius:0;margin:0;width:100%;max-width:100%;left:0;transform:translateX(0);position:relative;box-sizing:border-box;}.testimonial-item{border-radius:0;background-position:60% center;background-size:cover;flex:0 0 100%;margin-right:0;}.holger-slide{background-position:60% center !important;background-size:cover !important;}.testimonial-overlay{padding:50px 20px;border-radius:0;justify-content:center;align-items:flex-end;background:transparent;}.testimonial-text{font-size:13px;margin-bottom:35px;}.author-info h4{font-size:16px;margin-bottom:10px;}.author-info span{font-size:13px;}.nav-btn{width:35px;height:35px;}.nav-btn svg{width:14px;height:14px;}.carousel-nav{padding:0 20px 0 10px;width:100%;left:0;right:0;top:50%;transform:translateY(-50%);position:absolute;justify-content:space-between;display:flex;z-index:1000;margin:0;}.carousel-dots{bottom:5px;gap:12px;padding:8px 16px;}.dot{width:10px;height:10px;touch-action:manipulation;-webkit-tap-highlight-color:transparent;}.dot::before{content:'';position:absolute;top:-8px;left:-8px;right:-8px;bottom:-8px;background:transparent;z-index:-1;}.testimonial-content{max-width:90%;width:90%;text-align:center;}}
@media (max-width:576px){.testimonial-carousel{padding:0;margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;position:relative;width:100%;overflow-x:hidden;box-sizing:border-box;}.carousel-container{height:60vh;margin:0;width:100%;max-width:100%;left:0;transform:translateX(0);position:relative;box-sizing:border-box;}.testimonial-item{background-position:70% center;background-size:cover;flex:0 0 100%;margin-right:0;}.holger-slide{background-position:70% center !important;background-size:cover !important;}.testimonial-overlay{justify-content:center;align-items:flex-end;background:transparent;padding:30px 15px;}.testimonial-content{max-width:95%;width:95%;text-align:center;}.nav-btn{width:32px;height:32px;}.nav-btn svg{width:12px;height:12px;}.carousel-nav{padding:0 18px 0 8px;width:100%;left:0;right:0;top:50%;transform:translateY(-50%);position:absolute;justify-content:space-between;display:flex;z-index:1000;margin:0;}.carousel-dots{bottom:5px;gap:12px;padding:8px 16px;}.dot{touch-action:manipulation;-webkit-tap-highlight-color:transparent;}.dot::before{content:'';position:absolute;top:-10px;left:-10px;right:-10px;bottom:-10px;background:transparent;z-index:-1;}}
@media (max-width:480px){.testimonial-carousel{padding:0;margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;position:relative;width:100%;overflow-x:hidden;box-sizing:border-box;}.carousel-container{height:55vh;border-radius:0;margin:0;width:100%;max-width:100%;left:0;transform:translateX(0);position:relative;box-sizing:border-box;}.testimonial-item{border-radius:0;background-position:80% center;background-size:cover;flex:0 0 100%;margin-right:0;}.holger-slide{background-position:80% center !important;background-size:cover !important;}.testimonial-overlay{padding:25px 15px;border-radius:0;justify-content:center;align-items:flex-end;background:transparent;}.testimonial-text{font-size:12px;margin-bottom:25px;}.author-info h4{font-size:14px;margin-bottom:8px;}.author-info span{font-size:11px;}.nav-btn{width:30px;height:30px;}.nav-btn svg{width:11px;height:11px;}.carousel-nav{padding:0 15px 0 5px;width:100%;left:0;right:0;top:50%;transform:translateY(-50%);position:absolute;justify-content:space-between;display:flex;z-index:1000;margin:0;}.carousel-dots{bottom:3px;gap:10px;padding:6px 14px;}.dot{width:8px;height:8px;touch-action:manipulation;-webkit-tap-highlight-color:transparent;}.dot::before{content:'';position:absolute;top:-10px;left:-10px;right:-10px;bottom:-10px;background:transparent;z-index:-1;}.testimonial-content{max-width:100%;width:100%;text-align:center;}}
</style>

<script>
document.addEventListener('DOMContentLoaded',function(){const track=document.querySelector('.testimonial-track');const items=document.querySelectorAll('.testimonial-item');const dots=document.querySelectorAll('.dot');const prevBtn=document.querySelector('.prev-btn');const nextBtn=document.querySelector('.next-btn');const container=document.querySelector('.carousel-container');let currentSlide=0;const totalSlides=items.length;let isTransitioning=false;let autoPlayInterval;let startX=0;let currentX=0;let isDragging=false;const setupCarouselItems = () => {
    const isMobile = window.innerWidth <= 768;
    items.forEach((item, index) => {
        let itemGap = 0;
        let flexBasis = '100%';

        if (isMobile) {
            itemGap = index === items.length - 1 ? 0 : 10;
            flexBasis = `calc(100% - ${itemGap}px)`;
        } else {
            itemGap = index === items.length - 1 ? 0 : 30;
            flexBasis = `calc(100% - ${itemGap}px)`;
        }
        
        item.style.marginRight = `${itemGap}px`;
        item.style.flex = `0 0 ${flexBasis}`;
    });
};

const updateCarousel = () => {
    if (isTransitioning) return;
    isTransitioning = true;
    
    const itemWidth = items[0].getBoundingClientRect().width;
    const itemStyle = window.getComputedStyle(items[0]);
    const gap = parseFloat(itemStyle.marginRight);

    const translateValue = -currentSlide * (itemWidth + gap);
    track.style.transform = `translateX(${translateValue}px)`;
    
    items.forEach((item, index) => {
        item.classList.toggle('active', index === currentSlide);
    });
    dots.forEach((dot, index) => {
        dot.classList.toggle('active', index === currentSlide);
    });
    
    setTimeout(() => isTransitioning = false, 500);
};
const nextSlide=()=>{if(isTransitioning)return;currentSlide=(currentSlide+1)%totalSlides;updateCarousel();};const prevSlide=()=>{if(isTransitioning)return;currentSlide=(currentSlide-1+totalSlides)%totalSlides;updateCarousel();};const goToSlide=(index)=>{if(isTransitioning||index===currentSlide)return;currentSlide=index;updateCarousel();};const startAutoPlay=()=>{stopAutoPlay();autoPlayInterval=setInterval(nextSlide,15000);};const stopAutoPlay=()=>{if(autoPlayInterval){clearInterval(autoPlayInterval);autoPlayInterval=null;}};const getEventX=(e)=>e.type.includes('mouse')?e.clientX:e.touches[0].clientX;const handleStart=(e)=>{if(isTransitioning)return;if(e.target.closest('.nav-btn')||e.target.closest('.dot')||e.target.closest('.carousel-nav')||e.target.closest('.carousel-dots'))return;isDragging=true;startX=getEventX(e);currentX=startX;track.style.transition='none';stopAutoPlay();if(e.type.includes('touch'))e.preventDefault();if(e.type==='mousedown'){document.addEventListener('mousemove',handleMove);document.addEventListener('mouseup',handleEnd);e.preventDefault();}};const handleMove=(e)=>{if(!isDragging)return;e.preventDefault();currentX=getEventX(e);const deltaX=currentX-startX;const itemWidth=items[0].offsetWidth;const itemStyle=window.getComputedStyle(items[0]);const gap=parseFloat(itemStyle.marginRight);const baseTranslate=-currentSlide*(itemWidth+gap);const dragOffset=deltaX*0.3;track.style.transform=`translateX(${baseTranslate+dragOffset}px)`;};const handleEnd=(e)=>{if(!isDragging)return;isDragging=false;const deltaX=currentX-startX;const threshold=container.offsetWidth*0.15;track.style.transition='transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94)';if(Math.abs(deltaX)>threshold){deltaX>0?prevSlide():nextSlide();}else{updateCarousel();}if(e.type==='mouseup'){document.removeEventListener('mousemove',handleMove);document.removeEventListener('mouseup',handleEnd);}setTimeout(startAutoPlay,1000);};if(nextBtn){const handleNextClick=(e)=>{e.preventDefault();e.stopPropagation();if(!isTransitioning){stopAutoPlay();nextSlide();setTimeout(startAutoPlay,2000);}};nextBtn.addEventListener('click',handleNextClick);nextBtn.addEventListener('touchend',handleNextClick);nextBtn.addEventListener('touchstart',(e)=>{e.preventDefault();e.stopPropagation();});nextBtn.addEventListener('touchmove',(e)=>{e.preventDefault();e.stopPropagation();});nextBtn.addEventListener('mousedown',(e)=>{e.preventDefault();e.stopPropagation();});}if(prevBtn){const handlePrevClick=(e)=>{e.preventDefault();e.stopPropagation();if(!isTransitioning){stopAutoPlay();prevSlide();setTimeout(startAutoPlay,2000);}};prevBtn.addEventListener('click',handlePrevClick);prevBtn.addEventListener('touchend',handlePrevClick);prevBtn.addEventListener('touchstart',(e)=>{e.preventDefault();e.stopPropagation();});prevBtn.addEventListener('touchmove',(e)=>{e.preventDefault();e.stopPropagation();});prevBtn.addEventListener('mousedown',(e)=>{e.preventDefault();e.stopPropagation();});}items.forEach((item,index)=>{item.addEventListener('click',(e)=>{e.preventDefault();if(index!==currentSlide&&!isTransitioning){stopAutoPlay();goToSlide(index);setTimeout(startAutoPlay,2000);}});});dots.forEach((dot,index)=>{const handleDotClick=(e)=>{e.preventDefault();e.stopPropagation();if(!isTransitioning){stopAutoPlay();goToSlide(index);setTimeout(startAutoPlay,2000);}};dot.addEventListener('click',handleDotClick);dot.addEventListener('touchend',handleDotClick);dot.addEventListener('touchstart',(e)=>{e.preventDefault();e.stopPropagation();});dot.addEventListener('touchmove',(e)=>{e.preventDefault();e.stopPropagation();});dot.addEventListener('mousedown',(e)=>{e.preventDefault();e.stopPropagation();});});container?.addEventListener('touchstart',handleStart,{passive:false});container?.addEventListener('touchmove',handleMove,{passive:false});container?.addEventListener('touchend',handleEnd,{passive:false});container?.addEventListener('mousedown',handleStart);container?.addEventListener('contextmenu',e=>e.preventDefault());if(window.innerWidth>768&&!('ontouchstart' in window)){container?.addEventListener('mouseenter',stopAutoPlay);container?.addEventListener('mouseleave',startAutoPlay);}let resizeTimeout;window.addEventListener('resize',()=>{clearTimeout(resizeTimeout);resizeTimeout=setTimeout(()=>{setupCarouselItems();updateCarousel();stopAutoPlay();setTimeout(startAutoPlay,1000);},250);});window.addEventListener('orientationchange',()=>{setTimeout(()=>{setupCarouselItems();updateCarousel();stopAutoPlay();setTimeout(startAutoPlay,1000);},300);});document.addEventListener('visibilitychange',()=>{document.hidden?stopAutoPlay():startAutoPlay();});if(items.length>0&&track&&container){setupCarouselItems();updateCarousel();startAutoPlay();}});
</script>